	if (prctl(PR_SET_PDEATHSIG, SIGKILL, 0, 0, 0) == -1) {
		PLOG_E("prctl(PR_SET_PDEATHSIG, SIGKILL)");
		return false;
	}
	if (parent_fd != -1) {
		struct pollfd pfd = {.fd = parent_fd, .events = POLLIN, .revents = 0};
