+bool applyResourceLimitCombo(nsj_t* nsj) {
+	if (!nsj->njc.has_resource_limits()) {
+		return true;
+	}
+	if (nsj->njc.disable_rl()) {
+		LOG_E("resource_limits cannot be combined with disable_rl");
