+		nsj->njc.set_rlimit_fsize_type(nsjail::RLimit::VALUE);
+	}
+	if (combo.has_rlimit_nofile()) {
+		nsj->njc.set_rlimit_nofile(combo.rlimit_nofile());
+		nsj->njc.set_rlimit_nofile_type(nsjail::RLimit::VALUE);
